// Picks one representative raster image (if any) from the cluster's members
// and assembles the text portion of the vision prompt. Only ONE image is
// sent per cluster call (not every member) to keep this sub-workflow's node
// graph static/simple -- see docs/architecture-decision.md and n8n/README.md
// "Known simplifications". The full local/CI Python path (ai_client.py) does
// send up to 4 images per cluster; this is a deliberate, documented tradeoff
// for the n8n canvas.
const input = $json;
const members = input.members || [];

const rep = members.find(m => m.asset_type === "image" && m.extension !== "svg" && m.inspection_ok !== false);

const slim = members.map(m => ({
  asset_id: m.id, filename: m.filename, relpath: m.relpath, asset_type: m.asset_type,
  width: m.width, height: m.height, size_bytes: m.size_bytes, modified_at: m.modified_at,
  is_exact_duplicate_of_another_member: !!(m.exact_duplicate_of && m.exact_duplicate_of.length),
  visual_similarity_notes: [...(m.visually_similar_to || []), ...(m.visual_duplicate_of || [])],
}));

const mediaTypeFor = (ext) => ({
  jpg: "image/jpeg", jpeg: "image/jpeg", png: "image/png",
  webp: "image/webp", tif: "image/tiff", tiff: "image/tiff",
}[ext] || "image/png");

const SYSTEM_PROMPT = "You are an operational asset-management assistant for a creative agency delivery pipeline. You will be shown a group of files that a deterministic filename-matching step flagged as a possible \"version family\" (the same creative exported or revised multiple times), plus their technical metadata, and possibly one representative image.\n\nYour job is ONLY to reason about:\n- whether these files likely represent versions of the same creative, a set of duplicates, or unrelated files that happen to share a similar name\n- which file, if any, looks like the final/delivery-ready version vs. an intermediate/draft/source file\n- the general creative type (e.g. instagram_post, logo, reel_cover, banner, print_asset, unknown)\n- a short, neutral visual summary (subject/layout only)\n- whether any pair of members appears visually different despite the similar filename\n\nYou must NOT:\n- comment on artistic/design quality\n- claim certainty -- always return a confidence between 0 and 1\n- invent members not given to you\n\nRespond with ONLY a single JSON object, no markdown fences, no prose, matching exactly this shape (all fields required):\n{\n  \"cluster_id\": string,\n  \"relationship\": \"likely_version_family\" | \"likely_duplicate_set\" | \"unrelated_similar\" | \"unclear\",\n  \"confidence\": number 0-1,\n  \"creative_type\": string,\n  \"visual_summary\": string (<=400 chars, neutral, no quality judgement),\n  \"reason\": string (<=400 chars),\n  \"recommended_review\": boolean,\n  \"members\": [\n    {\"asset_id\": string, \"likely_role\": \"final\"|\"intermediate\"|\"source\"|\"duplicate\"|\"unknown\",\n     \"role_confidence\": number 0-1, \"differs_visually\": boolean}\n  ]\n}";

return [{
  json: {
    cluster_id: input.cluster_id,
    members,
    project_root: input.project_root,
    ai_mode: input.ai_mode || "auto",
    representative_relpath: rep ? rep.relpath : null,
    representative_media_type: rep ? mediaTypeFor(rep.extension) : null,
    user_payload_text: JSON.stringify({ cluster_id: input.cluster_id, members: slim }, null, 2),
    system_prompt: SYSTEM_PROMPT,
    attempt: 1,
  },
}];

// Attaches the representative image (base64, already loaded by the upstream
// Read/Write Files From Disk node) to the vision request body.
const b64 = $binary.image_data ? $binary.image_data.data : null;
if (!b64) {
  // File could not be read (e.g. moved/deleted between stages) -- degrade to text-only rather than fail the cluster.
  const body = {
    model: "claude-sonnet-4-6", max_tokens: 1024, system: $json.system_prompt,
    messages: [{ role: "user", content: [{ type: "text", text: $json.user_payload_text }] }],
  };
  return [{ json: { ...$json, request_body: body } }];
}
const body = {
  model: "claude-sonnet-4-6", max_tokens: 1024, system: $json.system_prompt,
  messages: [{
    role: "user",
    content: [
      { type: "text", text: $json.user_payload_text },
      { type: "image", source: { type: "base64", media_type: $json.representative_media_type, data: b64 } },
    ],
  }],
};
return [{ json: { ...$json, request_body: body } }];

const body = {
  model: "claude-sonnet-4-6", max_tokens: 1024, system: $json.system_prompt,
  messages: [{ role: "user", content: [{ type: "text", text: $json.user_payload_text }] }],
};
return [{ json: { ...$json, request_body: body } }];

// Hand-rolled JSON Schema check -- mirrors python/src/schemas.py
// AI_CLUSTER_ANALYSIS_SCHEMA exactly. Kept in sync manually; this is the
// n8n-side half of the "never trust raw model text" contract described in
// docs/architecture-decision.md Section 4.
const resp = $json;
const upstream = $('Select Representative Image + Build Text Payload').item.json;
const attempt = upstream.attempt || 1;

if (resp.error) {
  return [{ json: { valid: false, error: `HTTP error: ${JSON.stringify(resp.error).slice(0, 300)}`, attempt, cluster_id: upstream.cluster_id } }];
}

let parsed;
try {
  const blocks = (resp.content || []).filter(b => b.type === "text").map(b => b.text).join("");
  parsed = JSON.parse(blocks);
} catch (e) {
  return [{ json: { valid: false, error: `Could not parse model output as JSON: ${e.message}`, attempt, cluster_id: upstream.cluster_id } }];
}

function isNum01(v) { return typeof v === "number" && v >= 0 && v <= 1; }
const errors = [];
const REQUIRED = ["cluster_id", "relationship", "confidence", "creative_type", "visual_summary", "reason", "recommended_review", "members"];
for (const f of REQUIRED) if (!(f in parsed)) errors.push(`missing field '${f}'`);
if (parsed.relationship && !["likely_version_family", "likely_duplicate_set", "unrelated_similar", "unclear"].includes(parsed.relationship))
  errors.push("invalid 'relationship' enum value");
if (parsed.confidence !== undefined && !isNum01(parsed.confidence)) errors.push("'confidence' must be a number between 0 and 1");
if (!Array.isArray(parsed.members) || parsed.members.length === 0) errors.push("'members' must be a non-empty array");
else for (const m of parsed.members) {
  if (!m.asset_id) errors.push("member missing asset_id");
  if (!["final", "intermediate", "source", "duplicate", "unknown"].includes(m.likely_role)) errors.push(`invalid likely_role '${m.likely_role}'`);
  if (!isNum01(m.role_confidence)) errors.push("member role_confidence must be a number between 0 and 1");
  if (typeof m.differs_visually !== "boolean") errors.push("member differs_visually must be boolean");
}

if (errors.length) {
  return [{ json: { valid: false, error: errors.join("; "), attempt, cluster_id: upstream.cluster_id } }];
}

parsed.ai_mode = "live";
parsed.ai_error = null;
return [{ json: { valid: true, data: parsed, attempt, cluster_id: parsed.cluster_id } }];

const orig = $('Select Representative Image + Build Text Payload').item.json;
return [{
  json: {
    cluster_id: orig.cluster_id, relationship: "unclear", confidence: 0, creative_type: "unknown",
    visual_summary: "AI analysis failed schema validation after one retry; flagged for manual review.",
    reason: $json.error || "unknown validation error", recommended_review: true,
    ai_mode: "failed", ai_error: $json.error,
    members: orig.members.map(m => ({ asset_id: m.id, likely_role: "unknown", role_confidence: 0, differs_visually: false })),
  },
}];

// One retry only (matches python/src/ai_client.py MAX_RETRIES=2 total attempts).
// The retry is text-only (no re-read of the image) to keep this loop simple --
// its purpose is fixing JSON-formatting compliance, not re-examining the image.
const orig = $('Select Representative Image + Build Text Payload').item.json;
const hint = `\n\nYour previous response was invalid (${$json.error}). Return ONLY the JSON object, matching the schema exactly, with no markdown fences or extra text.`;
const body = {
  model: "claude-sonnet-4-6", max_tokens: 1024, system: orig.system_prompt,
  messages: [{ role: "user", content: [{ type: "text", text: orig.user_payload_text + hint }] }],
};
return [{ json: { ...orig, attempt: 2, request_body: body } }];
